package com.appcore.runtime

import android.app.ActivityManager
import android.content.Context
import android.content.pm.PackageManager
import java.io.File

/**
 * Anti-REA L101 — on-device modder-app block (MT Manager and friends).
 *
 * Detects Android apps that can open, edit, and repack a protected APK
 * on the phone itself (MT Manager, Apktool M, NP Manager, APK Editor,
 * Lucky Patcher, …). Full list + sources in
 * layers/MT-LIKE-BLOCKLIST.md. The package names are stored ONLY as
 * encrypted blobs in ModBlockData.kt (generated by
 * tools/gen_modblock_blobs.py) — plaintext names NEVER appear in this
 * file, in the runtime source, or in the protected APK's dex.
 *
 * REFUSE-ONLY. A finding means the protected app refuses ONE
 * sensitive action (login, buy, settle, key generation) while the
 * tool is present. This code NEVER deletes anything, NEVER kills
 * another app, NEVER touches the other app's data, NEVER roots, and
 * NEVER blocks launch. Every check catches all exceptions and returns
 * "not found" on error — a failed check must never crash the app.
 *
 * Honest limits (also in MT-LIKE-BLOCKLIST.md):
 * - A clone/repack with a different package name evades the
 *   package-name check. Running-process + known-directory checks are
 *   the second and third signals for exactly that reason.
 * - On Android 11+, PackageManager only sees packages the app
 *   declares in <queries> (or QUERY_ALL_PACKAGES). Anti-REA does NOT
 *   auto-inject <queries> (it would list the blocked names in
 *   plaintext in the manifest); without host-app <queries> entries
 *   the installed-check degrades to "not installed" and L101 falls
 *   back to the other two signals.
 * - A blocked app installed for lawful use on the owner's own apps
 *   is indistinguishable from one installed to attack this app.
 *   That false-positive tradeoff is disclosed in the blocklist doc.
 */
object ReaModBlock {

    /** One finding. `signal` is a package name (installed/running) or
     *  a directory path (dir). `source` is "installed", "running", or
     *  "dir". Evidence never contains secrets. */
    data class Finding(val signal: String, val source: String)

    // Well-known working directories of the blocked apps (public
    // folder names). Read-only File.exists() checks. The directory
    // path itself is the finding's signal — the owner package is
    // deliberately NOT stored here, so no blocklist package name
    // appears in plaintext in this file (see MT-LIKE-BLOCKLIST.md
    // for which app owns which folder).
    private val KNOWN_DIRS: List<String> = listOf(
        "/storage/emulated/0/MT2",
        "/storage/emulated/0/LuckyPatcher",
        "/storage/emulated/0/luckypatchers"
    )

    /**
     * Decrypt the blocklist in memory. A blob that fails integrity is
     * skipped (never crashes, never returns a wrong value); the
     * remaining entries still apply.
     */
    fun blockedPackages(): List<String> {
        val out = mutableListOf<String>()
        for ((blob, p1, p2) in ModBlockData.BLOCKED) {
            try {
                out.add(ReaRuntime.decrypt(blob, p1, p2))
            } catch (e: Exception) {
                // Tampered blob: drop this one entry, keep the rest.
                continue
            }
        }
        return out
    }

    /** Pure core (no Android APIs — JVM-testable): which of the
     *  installed package names are blocked, sorted, duplicates removed. */
    fun findBlocked(installed: Collection<String>): List<String> {
        val blocked = blockedPackages().toSet()
        return installed.filter { it in blocked }.distinct().sorted()
    }

    /** Pure core: true only for an exact (case-sensitive) blocklist hit. */
    fun isPackageBlocked(packageName: String): Boolean =
        packageName in blockedPackages().toSet()

    /** Installed-check via PackageManager (exact queries, one per
     *  blocked package). NameNotFoundException = not installed. Any
     *  other failure = treated as not installed, never throws. */
    @Suppress("DEPRECATION")
    fun checkInstalled(context: Context): List<Finding> {
        val out = mutableListOf<Finding>()
        val pm: PackageManager = try {
            context.packageManager
        } catch (e: Exception) {
            return emptyList()
        }
        for (pkg in blockedPackages()) {
            try {
                pm.getPackageInfo(pkg, 0)
                out.add(Finding(pkg, "installed"))
            } catch (e: PackageManager.NameNotFoundException) {
                // Not installed (or not visible on Android 11+ — see doc).
            } catch (e: Exception) {
                // Any other failure: treat as not installed, keep going.
            }
        }
        return out
    }

    /** Running-process check (best-effort on modern Android, which
     *  limits what getRunningAppProcesses returns). Compares process
     *  names exactly against the blocklist. Never throws. */
    fun checkRunning(context: Context): List<Finding> {
        val out = mutableListOf<Finding>()
        try {
            val am = context.getSystemService(Context.ACTIVITY_SERVICE)
                as? ActivityManager ?: return emptyList()
            val blocked = blockedPackages().toSet()
            val procs = try {
                am.runningAppProcesses
            } catch (e: Exception) {
                null
            } ?: return emptyList()
            for (proc in procs) {
                val name = proc?.processName ?: continue
                if (name in blocked) out.add(Finding(name, "running"))
            }
        } catch (e: Exception) {
            return out
        }
        return out.distinct()
    }

    /** Known-directory check (read-only File.exists, never reads or
     *  writes inside). Also checks Android/data/<blocked-package>
     *  dirs, built at runtime from the decrypted names. */
    fun checkKnownDirs(): List<Finding> {
        val out = mutableListOf<Finding>()
        try {
            for (dir in KNOWN_DIRS) {
                try {
                    if (File(dir).exists()) out.add(Finding(dir, "dir"))
                } catch (e: Exception) {
                    continue
                }
            }
            for (pkg in blockedPackages()) {
                try {
                    val dir = "/storage/emulated/0/Android/data/$pkg"
                    if (File(dir).exists()) out.add(Finding(dir, "dir"))
                } catch (e: Exception) {
                    continue
                }
            }
        } catch (e: Exception) {
            return out
        }
        return out
    }

    /** All three signals, de-duplicated by (signal, source). */
    fun checkAll(context: Context): List<Finding> {
        val all = mutableListOf<Finding>()
        try {
            all.addAll(checkInstalled(context))
        } catch (e: Exception) {
            // fall through to the other signals
        }
        try {
            all.addAll(checkRunning(context))
        } catch (e: Exception) {
            // fall through
        }
        try {
            all.addAll(checkKnownDirs())
        } catch (e: Exception) {
            // fall through
        }
        return all.distinct()
    }

    /** True when any signal fired. A signal, not proof — the app
     *  decides what it means (refuse a sensitive action). */
    fun isModToolPresent(context: Context): Boolean =
        try {
            checkAll(context).isNotEmpty()
        } catch (e: Exception) {
            false
        }

    /** Gate for sensitive entry points: true only when no modder
     *  tool was found. The app must call this BEFORE login, buy,
     *  settle, or key generation, and refuse the action when false. */
    fun allowSensitiveAction(context: Context): Boolean =
        !isModToolPresent(context)
}
